using Web.Common.Utils; using Web.Features.Accounts; using Web.Features.Properties.Services; using Web.Features.Search.Abstractions; using Web.Features.Search.DTOs;
namespace Web.Features.Search.Services;
public sealed class GlobalSearchService(IEnumerable<ISearchProvider> providers, P2CallerProvider callers, ILogger<GlobalSearchService> log) {
 public async Task<SearchResponse> SearchAsync(string? query,string? group,int limit,int offset,CancellationToken ct) { var raw=query?.Trim()??""; var normalized=TextSearchNormalizer.Normalize(raw); if(normalized.Length<2)return new([]); Web.Features.Properties.PropertyCaller caller; try { caller=await callers.GetCallerAsync(); } catch(UnauthorizedAccessException){return new([]);} if(caller.IsAdmin)return new([]); var ps=providers.Where(p=>string.IsNullOrEmpty(group)||p.GroupKey==group).ToArray(); var ctx=new SearchContext(caller,raw,normalized,Math.Max(1,limit),Math.Max(0,offset)); var rows=await Task.WhenAll(ps.Select(p=>Run(p,ctx,ct))); return new(rows.Where(x=>x is { Hits.Count:>0 }).Cast<SearchGroupResult>().OrderBy(x=>ps.First(p=>p.GroupKey==x.GroupKey).Order).ToArray()); }
 private async Task<SearchGroupResult?> Run(ISearchProvider p,SearchContext c,CancellationToken ct){using var t=CancellationTokenSource.CreateLinkedTokenSource(ct);t.CancelAfter(TimeSpan.FromSeconds(2));try{return await p.SearchAsync(c,t.Token);}catch(Exception ex) when(ex is not OperationCanceledException||!ct.IsCancellationRequested){log.LogWarning("Global search provider {Provider} failed: {Type}",p.GroupKey,ex.GetType().Name);return null;}}
}
